<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { request } from '../api/http';
import { session } from '../lib/session';
import '../styles/payables-native.css';

const loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),loadedAt=ref('');
const rows=ref([]),advances=ref([]),branches=ref([]),today=ref(dateKey(new Date()));
const branch=ref('ALL'),view=ref('dashboard'),search=ref(''),status=ref('ALL'),head=ref('ALL'),bucket=ref('ALL'),source=ref('ALL'),dueBefore=ref('');
const selected=ref(null),schedule=ref(null),plannerDetail=ref(null),completeForm=ref({head:'',branch:''}),vendor=ref(''),report=ref('age');
const drafts=ref([]),draftsLoaded=ref(false),draftFormOpen=ref(false),draftForm=ref({vendor:'',invoice:'',date:dateKey(new Date()),due:dateKey(new Date()),head:'',branch:'',amount:0,source:'Manual'});
const filtersOpen=ref(false);
const bookPage=ref(1),pageSize=50;
const horizon=ref(6),plannerView=ref('calendar'),plannerGroup=ref('head'),runRate=ref(true),ceilings=ref({}),salaryRows=ref([]),salaryLoading=ref(false),salaryError=ref('');
const recurringAssumptions=[
  {name:'Payroll — net salaries',head:'Salaries',amount:2196108,week:0,day:5,frequency:'Monthly'},
  {name:'TDS 192B — salary',head:'TDS Payable',amount:117768,week:0,day:7,frequency:'Monthly'},
  {name:'TDS 194C / 194I / 194J',head:'TDS Payable',amount:778929,week:0,day:7,frequency:'Monthly'},
  {name:'PF & ESI challan',head:'Statutory Contribution',amount:138406,week:2,day:15,frequency:'Monthly'},
  {name:'Professional tax',head:'Statutory Contribution',amount:7900,week:1,day:10,frequency:'Monthly'},
  {name:'Rent — six branches',head:'Rent',amount:1168212,week:0,day:5,frequency:'Monthly'},
  {name:'GST 3B — net cash',head:'GST Payable',amount:912855,week:2,day:20,frequency:'Monthly'},
  {name:'Housekeeping & security',head:'Housekeeping & Security',amount:414923,week:3,day:25,frequency:'Monthly'},
  {name:'Laundry — all units',head:'Laundry',amount:110581,week:3,day:25,frequency:'Monthly'},
  {name:'Advertisement retainer',head:'Advertisement',amount:156600,week:3,day:28,frequency:'Monthly'},
  {name:'Software AMC',head:'Software AMC',amount:22774,week:0,day:5,frequency:'Monthly'},
  {name:'Machinery AMC',head:'Machinery AMC',amount:104500,week:4,day:30,frequency:'Quarterly'},
  {name:'Consumables — purchase run rate',head:'Consumables',amount:480000,week:2,day:20,frequency:'Monthly',estimate:true},
];
const headRules=[['Rent',1,30],['TDS Payable',1,0],['GST Payable',1,0],['Housekeeping & Security',1,30],['Consumables',2,30],['Laundry',2,30],['Advertisement',3,45],['Professional Fees',3,30],['Machinery AMC',3,30],['Software AMC',3,30],['Software Development',3,45],['Office Supplies',3,30],['Repairs & Maintenance',3,30]];
let controller;

function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function amount(value){return Number(value||0).toLocaleString('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0});}
function dateText(value){if(!value)return '—';const d=new Date(`${String(value).slice(0,10)}T00:00:00`);return Number.isNaN(d.getTime())?String(value):d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});}
function apiError(message){return message||'Payables service returned an invalid response.';}
async function callApi(action,payload={},signal){const response=await request('payables_planner_api',{args:{action,...payload},csrfToken:session.csrf_token,signal});const result=response?.message;if(!result||result.ok===0||result.ok===false)throw new Error(apiError(result?.message));return result;}
async function load(){controller?.abort();controller=new AbortController();loading.value=true;error.value='';notice.value='';try{const result=await callApi('load',{},controller.signal);rows.value=(result.book||[]).map(normalize);advances.value=(result.advances||[]).map(normalize);branches.value=result.branches||[];today.value=result.today||today.value;if(!Object.keys(ceilings.value).length){try{ceilings.value=JSON.parse(localStorage.getItem('life-payables-ceilings')||'{}')}catch{ceilings.value={}}}if(!draftsLoaded.value){try{drafts.value=JSON.parse(localStorage.getItem('life-payables-drafts')||'[]').map(normalize)}catch{drafts.value=[]}draftsLoaded.value=true;}loadedAt.value=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});if(branch.value!=='ALL'&&!branches.value.includes(branch.value))branch.value='ALL';}catch(cause){if(cause.name!=='AbortError')error.value=cause.message||'Could not load the payable book.';}finally{loading.value=false;}}
function normalize(row){return{...row,a:Number(row.a||0),g:Number(row.g||0),inc:Number(row.inc||0),p:row.p&&typeof row.p==='object'?row.p:{},x:row.x||'R',src:row.src||'PI'};}
function inBranch(row){return branch.value==='ALL'||row.b===branch.value;}
function planned(row){return Object.values(row.p||{}).reduce((total,weeks)=>total+(Array.isArray(weeks)?weeks.reduce((s,n)=>s+Number(n||0),0):0),0);}
function unplanned(row){return Math.max(0,row.a-planned(row));}
function over(row){return Math.max(0,planned(row)-row.a);}
function ageing(row){return row.bk|| (row.g<=0?'Current':row.g<=30?'0-30':row.g<=60?'31-60':row.g<=90?'61-90':row.g<=120?'91-120':'120+');}
function isStatutory(row){return ['TDS Payable','GST Payable','Statutory Contribution'].includes(row.e);}
const scoped=computed(()=>[...rows.value,...drafts.value].filter(inBranch));
const scopedLive=computed(()=>rows.value.filter(inBranch));
const filtered=computed(()=>scoped.value.filter(row=>{
  const q=search.value.trim().toLowerCase();
  if(q&&!`${row.i} ${row.n} ${row.v} ${row.e} ${row.b} ${row.s}`.toLowerCase().includes(q))return false;
  if(head.value==='__NONE__'&&row.e)return false;if(head.value!=='ALL'&&head.value!=='__NONE__'&&row.e!==head.value)return false;
  if(bucket.value!=='ALL'&&ageing(row)!==bucket.value)return false;
  if(source.value!=='ALL'&&row.src!==source.value)return false;
  if(status.value==='UNP'&&unplanned(row)<=0||status.value==='H'&&row.x!=='H'||status.value==='INC'&&!row.inc||status.value==='OVR'&&over(row)<=0||status.value==='SCHEDULED'&&unplanned(row)>0||status.value==='ALL'&&false)return false;
  if(dueBefore.value&&row.u>dueBefore.value)return false;
  return true;
}));
const visibleRows=computed(()=>filtered.value.slice((bookPage.value-1)*pageSize,bookPage.value*pageSize));
watch(filtered,()=>{bookPage.value=1;});
const heads=computed(()=>[...new Set(rows.value.map(row=>row.e).filter(Boolean))].sort());
const totals=computed(()=>{const outstanding=scopedLive.value.reduce((s,row)=>s+row.a,0),scheduled=scopedLive.value.reduce((s,row)=>s+planned(row),0);return{outstanding,scheduled,unplanned:scopedLive.value.reduce((s,row)=>s+unplanned(row),0),overdue:scopedLive.value.filter(row=>row.g>0).reduce((s,row)=>s+row.a,0),older90:scopedLive.value.filter(row=>row.g>90).reduce((s,row)=>s+row.a,0),held:scopedLive.value.filter(row=>row.x==='H').reduce((s,row)=>s+row.a,0),incomplete:scopedLive.value.filter(row=>row.inc).length,overCount:scopedLive.value.filter(row=>over(row)>0).length};});
const ageingRows=computed(()=>['Current','0-30','31-60','61-90','91-120','120+'].map(name=>{const list=scoped.value.filter(row=>ageing(row)===name);return{name,count:list.length,vendors:new Set(list.map(row=>row.v)).size,outstanding:list.reduce((s,row)=>s+row.a,0),scheduled:list.reduce((s,row)=>s+planned(row),0),unplanned:list.reduce((s,row)=>s+unplanned(row),0)}}));
const vendors=computed(()=>{const map=new Map();scoped.value.forEach(row=>{const item=map.get(row.v)||{name:row.v,count:0,outstanding:0,scheduled:0,oldest:0};item.count++;item.outstanding+=row.a;item.scheduled+=planned(row);item.oldest=Math.max(item.oldest,row.g);map.set(row.v,item)});return[...map.values()].sort((a,b)=>b.outstanding-a.outstanding)});
const possibleVendorAliases=computed(()=>{const map=new Map();scoped.value.forEach(row=>{const key=String(row.v||'').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,12);if(!key)return;if(!map.has(key))map.set(key,new Set());map.get(key).add(row.v)});return[...map.values()].filter(names=>names.size>1).map(names=>[...names].sort()).sort((a,b)=>b.length-a.length)});
const selectedRows=computed(()=>vendor.value?scoped.value.filter(row=>row.v===vendor.value).sort((a,b)=>b.g-a.g):[]);
const branchOptions=computed(()=>['ALL',...branches.value]);
const plannerMonths=computed(()=>{const base=new Date(`${today.value}T00:00:00`);return Array.from({length:12},(_,i)=>{const d=new Date(base.getFullYear(),base.getMonth()+i,1);return dateKey(d).slice(0,7)});});
const plannerHorizonMonths=computed(()=>plannerMonths.value.slice(0,horizon.value));
const monthLabel=key=>new Date(`${key}-01T00:00:00`).toLocaleDateString('en-IN',{month:'long',year:'numeric'});
function recurringFor(month){const index=plannerMonths.value.indexOf(month);if(index<1)return[];const branchShare=branch.value==='ALL'?1:1/Math.max(1,branches.value.length);return recurringAssumptions.filter(row=>(!row.estimate||runRate.value)&&(row.frequency!=='Quarterly'||(index-1)%3===1)).map(row=>({...row,amount:Math.round(row.amount*branchShare)}));}
const plannerTotals=computed(()=>plannerHorizonMonths.value.map(month=>{const invoices=scoped.value.reduce((s,row)=>s+schedMonth(row,month),0),recurring=recurringFor(month).reduce((s,row)=>s+row.amount,0),ceiling=Number(ceilings.value[month]??defaultCeiling(month))*(branch.value==='ALL'?1:1/Math.max(1,branches.value.length));return{month,invoices,recurring,total:invoices+recurring,ceiling,headroom:ceiling-invoices-recurring,rows:scoped.value.filter(row=>schedMonth(row,month)>0).length+recurringFor(month).length}}));
const plannerWeekRows=computed(()=>plannerHorizonMonths.value.map(month=>{const weeks=Array.from({length:5},(_,week)=>({week,total:scoped.value.reduce((s,row)=>s+Number(row.p?.[month]?.[week]||0),0)+recurringFor(month).filter(row=>row.week===week).reduce((s,row)=>s+row.amount,0)}));return{month,weeks,total:weeks.reduce((s,row)=>s+row.total,0)}}));
const plannerDetailRows=computed(()=>{if(!plannerDetail.value)return[];const{month,week}=plannerDetail.value;const bills=scoped.value.filter(row=>Number.isInteger(week)?Number(row.p?.[month]?.[week]||0)>0:schedMonth(row,month)>0).map(row=>({kind:'ERP bill',name:row.v,reference:row.i,head:row.e||'Unassigned',amount:Number.isInteger(week)?Number(row.p?.[month]?.[week]||0):schedMonth(row,month),row}));const recurring=recurringFor(month).filter(row=>!Number.isInteger(week)||row.week===week).map(row=>({kind:row.estimate?'Estimate':'Recurring assumption',name:row.name,reference:'Reference forecast',head:row.head,amount:row.amount,row:null}));return[...bills,...recurring].sort((a,b)=>Number.isInteger(week)?(Number(a.row?.p?.[month]?.[week]||0)-Number(b.row?.p?.[month]?.[week]||0)):b.amount-a.amount);});
const plannerGroupedRows=computed(()=>{const map=new Map();scoped.value.forEach(row=>{const key=plannerGroup.value==='vendor'?row.v:plannerGroup.value==='branch'?row.b:row.e||'Unassigned',item=map.get(key)||{name:key,outstanding:0,scheduled:0,months:{}};item.outstanding+=row.a;plannerHorizonMonths.value.forEach(month=>{item.months[month]=(item.months[month]||0)+schedMonth(row,month)});item.scheduled+=planned(row);map.set(key,item)});return[...map.values()].sort((a,b)=>b.scheduled-a.scheduled)});
const salaryMonths=computed(()=>{const map=new Map();salaryRows.value.forEach(row=>{const key=String(row.start_date||row.posting_date||'').slice(0,7);if(!key)return;const item=map.get(key)||{month:key,count:0,net:0,slips:[]};item.count++;item.net+=Number(row.base_net_pay||row.net_pay||0);item.slips.push(row);map.set(key,item)});return[...map.values()].sort((a,b)=>b.month.localeCompare(a.month));});
function schedMonth(row,month){const value=row.p?.[month];return Array.isArray(value)?value.reduce((s,n)=>s+Number(n||0),0):0;}
async function loadSalary(){salaryLoading.value=true;salaryError.value='';try{const result=await callApi('v3_load');salaryRows.value=result.payroll||[];if(result.issues?.length)salaryError.value=result.issues.join(' ');}catch(cause){salaryRows.value=[];salaryError.value=cause.message||'Salary Slip report is not available for this account.';}finally{salaryLoading.value=false;}}
function openSchedule(row){if(row.inc){error.value='Complete the missing expense head and branch before scheduling.';return}if(row.x==='H'){error.value='Release this held bill before scheduling.';return}schedule.value={row,plan:JSON.parse(JSON.stringify(row.p||{}))};}
function scheduleMonthTotal(plan,month){return Array.isArray(plan?.[month])?plan[month].reduce((s,n)=>s+Number(n||0),0):0;}
function openPlannerDetail(month,week=null){plannerDetail.value={month,week};}
const editingTotal=computed(()=>schedule.value?Object.values(schedule.value.plan).reduce((total,weeks)=>total+(Array.isArray(weeks)?weeks.reduce((s,n)=>s+Number(n||0),0):0),0):0);
function setWeek(month,index,value){if(!schedule.value.plan[month])schedule.value.plan[month]=[0,0,0,0,0];schedule.value.plan[month][index]=Math.max(0,Number(value||0));}
function quickSchedule(mode){const row=schedule.value?.row;if(!row)return;const plan={};const place=(month,week,value)=>{if(!plan[month])plan[month]=[0,0,0,0,0];plan[month][week]=value;};if(mode==='now'){const d=new Date(`${today.value}T00:00:00`);d.setDate(d.getDate()+7);place(dateKey(d).slice(0,7),Math.min(4,Math.ceil(d.getDate()/7)-1),row.a);}if(mode==='due'){const date=row.u||today.value;place(date.slice(0,7),Math.min(4,Math.ceil(Number(date.slice(8,10))/7)-1),row.a);}if(mode==='3'||mode==='6'){const count=Number(mode),portion=Math.floor(row.a/count);for(let i=0;i<count;i++){const month=plannerMonths.value[i+1]||plannerMonths.value.at(-1);place(month,2,i===count-1?row.a-portion*(count-1):portion);}}schedule.value.plan=plan;}
async function saveSchedule(){const editor=schedule.value;if(!editor)return;if(editingTotal.value>editor.row.a+.01){error.value='The schedule cannot exceed the open balance.';return}const plan=Object.fromEntries(Object.entries(editor.plan).filter(([,weeks])=>Array.isArray(weeks)&&weeks.some(value=>Number(value)>0)));if(editor.row.localDraft){editor.row.p=plan;persistDrafts();schedule.value=null;notice.value='Draft schedule saved in this browser only; no ERP record changed.';return}await write('save_plan',{name:editor.row.i,src:editor.row.src,plan:JSON.stringify(plan)},()=>{editor.row.p=plan;schedule.value=null;});}
async function write(action,payload,success){saving.value=true;error.value='';try{await callApi(action,payload);success?.();await load();notice.value='Saved to the payables record.';}catch(cause){error.value=cause.message||'Could not save the payables change.';}finally{saving.value=false;}}
function openComplete(row){selected.value=row;completeForm.value={head:row.e||'',branch:row.b==='Unassigned'?'':row.b};}
async function completeLine(){if(!selected.value||!completeForm.value.head.trim()||!completeForm.value.branch){error.value='Enter the expense head and branch to complete this record.';return}const row=selected.value;await write('complete',{name:row.i,src:row.src,head:completeForm.value.head.trim(),branch:completeForm.value.branch},()=>{row.e=completeForm.value.head.trim();row.b=completeForm.value.branch;row.inc=0;selected.value=null;});}
async function toggleHold(row){if(isStatutory(row)){error.value='Statutory liabilities cannot be put on hold.';return}const hold=row.x==='H'?0:1;if(row.localDraft){row.x=hold?'H':'R';if(hold)row.p={};persistDrafts();notice.value='Draft hold updated in this browser only.';return}await write('set_hold',{name:row.i,src:row.src,hold,reason:hold?`Held from Vue Payables Planner on ${today.value}`:''},()=>{row.x=hold?'H':'R';if(hold)row.p={};});}
async function bulkSchedule(){const target=plannerMonths.value[1]||plannerMonths.value[0],pending=scoped.value.filter(row=>row.x!=='H'&&!row.inc&&unplanned(row)>0).sort((a,b)=>{const ap=headRules.find(rule=>rule[0]===a.e)?.[1]||3,bp=headRules.find(rule=>rule[0]===b.e)?.[1]||3;return ap-bp});if(!pending.length){notice.value='No schedulable unplanned balances in this branch scope.';return}saving.value=true;error.value='';let count=0;try{for(const row of pending){const plan=JSON.parse(JSON.stringify(row.p||{}));if(!Array.isArray(plan[target]))plan[target]=[0,0,0,0,0];const priority=headRules.find(rule=>rule[0]===row.e)?.[1]||3,week=priority===1?0:2;plan[target][week]+=unplanned(row);if(row.localDraft){row.p=plan;count++;continue}await callApi('save_plan',{name:row.i,src:row.src,plan:JSON.stringify(plan)});count++;}persistDrafts();await load();notice.value=`Auto-scheduled ${count} line(s) into ${monthLabel(target)}. Draft schedules stay in this browser; review the plan before payment.`;}catch(cause){error.value=`Auto-scheduling stopped after ${count} line(s): ${cause.message||'save failed'}`;await load();}finally{saving.value=false;}}
async function pushDiscretionary(month){const next=plannerMonths.value[plannerMonths.value.indexOf(month)+1];if(!next){error.value='No later month is available in the selected horizon.';return}const candidates=scoped.value.filter(row=>(headRules.find(rule=>rule[0]===row.e)?.[1]||3)===3&&schedMonth(row,month)>0);if(!candidates.length){notice.value='No discretionary scheduled rows can move from this month.';return}saving.value=true;error.value='';let count=0;try{for(const row of candidates){const plan=JSON.parse(JSON.stringify(row.p||{})),amountToMove=schedMonth(row,month);plan[month]=[0,0,0,0,0];if(!Array.isArray(plan[next]))plan[next]=[0,0,0,0,0];plan[next][2]+=amountToMove;if(row.localDraft){row.p=plan;count++;continue}await callApi('save_plan',{name:row.i,src:row.src,plan:JSON.stringify(plan)});count++;}persistDrafts();await load();notice.value=`Moved discretionary allocations for ${count} line(s) from ${monthLabel(month)} to ${monthLabel(next)}.`;}catch(cause){error.value=`Move stopped after ${count} line(s): ${cause.message||'save failed'}`;await load();}finally{saving.value=false;}}
function saveCeilings(){try{localStorage.setItem('life-payables-ceilings',JSON.stringify(ceilings.value));notice.value='Cash ceilings saved in this browser only. They are planning assumptions and are not ERP controls.';}catch{error.value='Could not save the browser-local ceiling assumptions.';}}
function setCeiling(month,value){ceilings.value={...ceilings.value,[month]:Math.max(0,Number(value||0))};}
function defaultCeiling(month){return plannerMonths.value.indexOf(month)===0?4500000:6800000;}
function resetCeilings(){ceilings.value={};try{localStorage.removeItem('life-payables-ceilings')}catch{}notice.value='Browser-local ceilings reset to the reference defaults.';}
function openRow(row){selected.value=row;completeForm.value={head:row.e||'',branch:row.b==='Unassigned'?'':row.b};}
function closeDialogs(){selected.value=null;schedule.value=null;plannerDetail.value=null;}
function setView(name){view.value=name;error.value='';notice.value='';if(name==='paysheet'&&!salaryRows.value.length&&!salaryLoading.value)loadSalary();}
function setReport(name){report.value=name;view.value='reports';if(name==='salary'&&!salaryRows.value.length)loadSalary();}
function resetFilters(){search.value='';status.value='ALL';head.value='ALL';bucket.value='ALL';source.value='ALL';dueBefore.value='';}
function persistDrafts(){try{localStorage.setItem('life-payables-drafts',JSON.stringify(drafts.value));}catch{error.value='Could not save browser-local bill drafts.';}}
function addDraft(){const form=draftForm.value;if(!form.vendor.trim()||!form.invoice.trim()||!form.date||!form.due||!form.head.trim()||!form.branch||Number(form.amount)<=0){error.value='Enter supplier, invoice, dates, expense head, branch and an amount greater than zero.';return}const row=normalize({i:`DRAFT-${Date.now()}`,n:form.invoice.trim(),v:form.vendor.trim(),b:form.branch,e:form.head.trim(),s:form.source,d:form.date,u:form.due,a:Number(form.amount),g:Math.max(0,Math.floor((new Date(`${today.value}T00:00:00`)-new Date(`${form.due}T00:00:00`))/86400000)),bk:'',x:'R',inc:0,p:{},localDraft:true});drafts.value=[row,...drafts.value];persistDrafts();draftForm.value={vendor:'',invoice:'',date:today.value,due:today.value,head:'',branch:'',amount:0,source:'Manual'};draftFormOpen.value=false;view.value='book';notice.value='Bill captured as a browser-local planning draft; no ERP invoice was created.';}
function deleteDraft(row){drafts.value=drafts.value.filter(item=>item.i!==row.i);persistDrafts();selected.value=null;notice.value='Browser-local planning draft deleted.';}
function exportRows(list=filtered.value,name='payables.csv'){const columns=['Reference','Invoice','Supplier','Branch','Expense head','Source','Posting date','Due date','Days overdue','Ageing bucket','Outstanding','Scheduled','Unplanned','Status'];const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const csv=[columns.map(quote).join(','),...list.map(row=>[row.i,row.n,row.v,row.b,row.e,row.s,row.d,row.u,row.g,ageing(row),row.a,planned(row),unplanned(row),row.x==='H'?'On hold':row.inc?'Incomplete':'Open'].map(quote).join(','))].join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=name;link.click();URL.revokeObjectURL(link.href);}
function exportReport(){const fields=report.value==='age'?['name','vendors','count','outstanding','scheduled','unplanned']:report.value==='vendors'?['name','count','oldest','outstanding','scheduled']:report.value==='head'?['head','outstanding','scheduled','unplanned']:report.value==='salary'?['month','count','net']:['i','n','v','b','e','s','d','u','g','a','x'];const labels={name:'Ageing bucket',vendors:'Vendors',count:'Lines',outstanding:'Outstanding',scheduled:'Scheduled',unplanned:'Unplanned',oldest:'Oldest overdue days',head:'Expense head',month:'Salary month',net:'Salary net pay',i:'Reference',n:'Invoice',v:'Supplier',b:'Branch',e:'Expense head',s:'Source',d:'Posting date',u:'Due date',g:'Days overdue',a:'Open balance',x:'Hold status'};const data=reportRows(),quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[fields.map(key=>quote(labels[key]||key)).join(','),...data.map(row=>fields.map(key=>quote(key==='x'?(row.x==='H'?row.hr||'On hold':'Open'):row[key])).join(','))];const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/csv;charset=utf-8'}));link.download=`payables-${report.value}.csv`;link.click();URL.revokeObjectURL(link.href);}
function reportRows(){if(report.value==='age')return ageingRows.value;if(report.value==='vendors')return vendors.value;if(report.value==='unplanned')return scoped.value.filter(row=>unplanned(row)>0).sort((a,b)=>unplanned(b)-unplanned(a));if(report.value==='stat')return scoped.value.filter(isStatutory).sort((a,b)=>String(a.u).localeCompare(String(b.u)));if(report.value==='hold')return scoped.value.filter(row=>row.x==='H').sort((a,b)=>b.g-a.g);if(report.value==='advice'){const end=new Date(`${today.value}T00:00:00`);end.setDate(end.getDate()+7);const cutoff=dateKey(end);return scoped.value.filter(row=>row.x!=='H'&&row.u>=today.value&&row.u<=cutoff).sort((a,b)=>String(a.u).localeCompare(String(b.u)));}if(report.value==='calendar')return scoped.value.filter(row=>isStatutory(row)&&row.u>=today.value&&row.u<=dateKey(new Date(new Date(`${today.value}T00:00:00`).setFullYear(new Date(`${today.value}T00:00:00`).getFullYear()+1)))).sort((a,b)=>String(a.u).localeCompare(String(b.u)));if(report.value==='head'){const map=new Map();scoped.value.forEach(row=>{const key=row.e||'Unassigned',x=map.get(key)||{head:key,outstanding:0,scheduled:0,unplanned:0};x.outstanding+=row.a;x.scheduled+=planned(row);x.unplanned+=unplanned(row);map.set(key,x)});return[...map.values()].sort((a,b)=>b.outstanding-a.outstanding)}if(report.value==='salary')return salaryMonths.value;return[];}
onMounted(load);onBeforeUnmount(()=>controller?.abort());
</script>

<template>
  <main class="payables-native">
    <header class="payables-head"><div><span class="payables-kicker">FINANCE · LIVE ERP PAYABLES</span><h1>Payables Planner</h1><p>Open supplier balances, due dates, saved payout schedules and branch exposure.</p></div><div class="payables-head-tools"><label>Branch scope<select v-model="branch"><option v-for="item in branchOptions" :key="item" :value="item">{{ item==='ALL'?'All branches':item }}</option></select></label><button :disabled="loading" @click="load">{{ loading?'Refreshing…':'↻ Refresh' }}</button><small v-if="loadedAt">Updated {{ loadedAt }}</small></div></header>
    <nav class="payables-nav"><button v-for="[id,label] in [['dashboard','Overview'],['book','Payables book'],['planner','Payout planner'],['advances','Advances & credits'],['paysheet','Salary register'],['vendors','Vendors'],['reports','Reports'],['masters','Masters']]" :key="id" :class="{active:view===id}" @click="setView(id)">{{ label }}</button></nav>
    <div v-if="error" class="payables-alert error" role="alert">{{ error }}<button @click="error=''">Dismiss</button></div><div v-if="notice" class="payables-alert success" role="status">{{ notice }}</div>
    <section v-if="view==='dashboard'" class="payables-content">
      <div class="payables-welcome"><div><h2>Payables overview</h2><p>Current ERP balances, their ageing and how much already has a payout date.</p></div><div><button class="payables-primary" @click="setView('book')">Review payable book</button><button @click="setView('planner')">Open payout planner</button></div></div>
      <div class="payables-cards"><button @click="setView('book')"><span>Total open payable · live ERP</span><strong>{{ amount(totals.outstanding) }}</strong><small>{{ scopedLive.length }} open ERP lines</small></button><button @click="setView('book')"><span>Browser-local drafts</span><strong>{{ amount(drafts.filter(inBranch).reduce((s,row)=>s+row.a,0)) }}</strong><small>{{ drafts.filter(inBranch).length }} draft lines · excluded from ERP totals</small></button><button @click="setView('reports');setReport('age')"><span>Overdue</span><strong>{{ amount(totals.overdue) }}</strong><small>Open invoices past due date</small></button><button @click="setView('planner')"><span>Scheduled</span><strong>{{ amount(totals.scheduled) }}</strong><small>{{ totals.outstanding?Math.round(totals.scheduled/totals.outstanding*100):0 }}% of the open book</small></button><button @click="setView('book');status='UNP'"><span>Unplanned balance</span><strong>{{ amount(totals.unplanned) }}</strong><small>Needs a payout date</small></button><button @click="setView('book');status='H'"><span>On hold</span><strong>{{ amount(totals.held) }}</strong><small>Held supplier balances</small></button><button @click="setView('book');status='INC'"><span>Incomplete records</span><strong>{{ totals.incomplete }}</strong><small>Missing head or branch</small></button></div>
      <div class="payables-grid"><section class="payables-panel"><div class="payables-panel-head"><div><h2>Ageing profile</h2><p>Outstanding balance by days overdue.</p></div><button @click="setView('reports');setReport('age')">Open report →</button></div><div v-for="item in ageingRows" :key="item.name" class="payables-bar-row"><span>{{ item.name }}</span><div><i :style="{width:`${totals.outstanding?Math.max(item.outstanding?3:0,item.outstanding/totals.outstanding*100):0}%`}"></i></div><strong>{{ amount(item.outstanding) }}</strong><small>{{ item.count }} lines</small></div></section><section class="payables-panel"><div class="payables-panel-head"><div><h2>Largest vendor balances</h2><p>Open supplier exposure in this scope.</p></div><button @click="setView('vendors')">All vendors →</button></div><div v-for="item in vendors.slice(0,7)" :key="item.name" class="payables-vendor-row"><button @click="vendor=item.name;setView('vendors')">{{ item.name }}</button><strong>{{ amount(item.outstanding) }}</strong><small>{{ item.count }} open</small></div><p v-if="!vendors.length" class="payables-empty">No open supplier balances in this scope.</p></section></div>
    </section>
    <section v-else-if="view==='book'" class="payables-content"><div class="payables-panel-head"><div><h2>Payables book</h2><p>{{ filtered.length }} of {{ scoped.length }} open line(s) · select a row to complete, schedule or hold it.</p></div><div><button class="payables-primary" @click="draftFormOpen=!draftFormOpen">{{ draftFormOpen?'Close bill capture':'+ Capture bill' }}</button><button @click="filtersOpen=!filtersOpen">{{ filtersOpen?'Hide filters':'Filters' }}</button><button @click="exportRows()">Export CSV</button></div></div><section v-if="draftFormOpen" class="payables-panel payables-draft-form"><div class="payables-alert info"><span>Planning draft only. This is stored in this browser and will not create an ERP invoice.</span></div><div class="payables-draft-fields"><label>Supplier<input v-model="draftForm.vendor" required placeholder="Supplier name"></label><label>Invoice number<input v-model="draftForm.invoice" required placeholder="Invoice reference"></label><label>Posting date<input v-model="draftForm.date" type="date" required></label><label>Due date<input v-model="draftForm.due" type="date" required></label><label>Expense head<input v-model="draftForm.head" list="payables-draft-heads" required placeholder="Choose or enter expense head"><datalist id="payables-draft-heads"><option v-for="item in [...new Set([...heads,...headRules.map(rule=>rule[0])])].sort()" :key="item" :value="item"></option></datalist></label><label>Branch<select v-model="draftForm.branch" required><option value="">Choose branch</option><option v-for="item in branches" :key="item">{{ item }}</option></select></label><label>Amount<input v-model.number="draftForm.amount" type="number" min="0.01" step="0.01" required></label><label>Source<select v-model="draftForm.source"><option>Manual</option><option>Invoice email</option><option>Purchase order</option><option>Other</option></select></label></div><div class="payables-draft-actions"><button @click="draftFormOpen=false">Cancel</button><button class="payables-primary" @click="addDraft">Save local draft</button></div></section><div v-if="filtersOpen" class="payables-filters"><label>Search<input v-model="search" type="search" placeholder="Supplier, invoice or reference"></label><label>Status<select v-model="status"><option value="ALL">All lines</option><option value="UNP">Unplanned</option><option value="SCHEDULED">Fully scheduled</option><option value="OVR">Over-committed</option><option value="H">On hold</option><option value="INC">Incomplete</option></select></label><label>Expense head<select v-model="head"><option value="ALL">All heads</option><option value="__NONE__">Unassigned</option><option v-for="item in heads" :key="item">{{ item }}</option></select></label><label>Ageing<select v-model="bucket"><option value="ALL">All buckets</option><option v-for="item in ['Current','0-30','31-60','61-90','91-120','120+']" :key="item">{{ item }}</option></select></label><label>Source<select v-model="source"><option value="ALL">All sources</option><option value="PI">Purchase Invoice</option><option value="JE">Journal Entry</option><option value="PE">Payment Entry</option></select></label><label>Due by<input v-model="dueBefore" type="date"></label><button @click="resetFilters">Reset</button></div><div class="payables-table-wrap"><table><thead><tr><th>Reference / invoice</th><th>Supplier</th><th>Branch</th><th>Expense head</th><th>Due date</th><th>Ageing</th><th>Outstanding</th><th>Scheduled</th><th>Status</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.src+'::'+row.i" @click="openRow(row)"><td><button class="payables-link">{{ row.i }}</button><small>{{ row.n }} · {{ row.localDraft?'Local draft · browser only':row.s }}</small></td><td>{{ row.v }}</td><td>{{ row.b||'Unassigned' }}</td><td>{{ row.e||'Unassigned' }}</td><td>{{ dateText(row.u) }}</td><td><span class="payables-badge" :class="{'critical':row.g>90,'warning':row.g>0&&row.g<=90}">{{ ageing(row) }}<small v-if="row.g>0"> · {{ row.g }}d</small></span></td><td class="numeric">{{ amount(row.a) }}</td><td class="numeric">{{ amount(planned(row)) }}</td><td><span class="payables-badge" :class="{critical:row.inc||over(row)>0,warning:row.x==='H'}">{{ row.localDraft?'Draft only':row.inc?'Incomplete':row.x==='H'?'On hold':over(row)>0?'Over-committed':unplanned(row)===0?'Scheduled':planned(row)>0?'Part scheduled':'Unplanned' }}</span></td></tr><tr v-if="!filtered.length"><td colspan="9" class="payables-empty">{{ loading?'Loading the payable book…':'No payable rows match these filters.' }}</td></tr></tbody></table></div><div class="payables-pagination"><button :disabled="bookPage<=1" @click="bookPage--">Previous</button><span>Page {{ bookPage }} of {{ Math.max(1,Math.ceil(filtered.length/pageSize)) }} · showing {{ visibleRows.length }} of {{ filtered.length }}</span><button :disabled="bookPage>=Math.ceil(filtered.length/pageSize)" @click="bookPage++">Next</button></div></section>
    <section v-else-if="view==='planner'" class="payables-content">
      <div class="payables-panel-head"><div><h2>Payout planner</h2><p>Saved ERP weekly allocations plus the clearly identified recurring forecast assumptions.</p></div><button @click="setView('book');status='UNP'">Schedule unplanned balances →</button></div>
      <div class="payables-panel payables-assumption"><strong>Forecast assumptions</strong><p>Recurring commitments and monthly ceilings below are reference values carried forward from the legacy planner. They are not ERP records and are not submitted or saved to the ERP. The purchase run rate is an estimate.</p><label><input v-model="runRate" type="checkbox"> Include estimated consumables purchase run rate</label></div>
      <div class="payables-planner-tools"><div><span>Horizon</span><button v-for="months in [3,6,9,12]" :key="months" :class="{active:horizon===months}" @click="horizon=months">{{ months }} months</button></div><div><span>View</span><button v-for="[id,label] in [['calendar','Calendar'],['rows','Rows'],['ladder','Cash ladder']]" :key="id" :class="{active:plannerView===id}" @click="plannerView=id">{{ label }}</button></div><button :disabled="saving||!totals.unplanned" @click="bulkSchedule">{{ saving?'Scheduling…':'Auto-schedule unplanned balances' }}</button></div>
      <div class="payables-cards"><article><span>Open ERP balance</span><strong>{{ amount(totals.outstanding) }}</strong></article><article><span>ERP allocations · horizon</span><strong>{{ amount(plannerTotals.reduce((s,row)=>s+row.invoices,0)) }}</strong></article><article><span>Recurring reference forecast · horizon</span><strong>{{ amount(plannerTotals.reduce((s,row)=>s+row.recurring,0)) }}</strong></article><article><span>Months above assumed ceiling</span><strong>{{ plannerTotals.filter(row=>row.headroom<0).length }}</strong></article></div>
      <section v-if="plannerView==='calendar'" class="payables-planner-months"><article v-for="item in plannerWeekRows" :key="item.month" class="payables-panel"><header><div><button class="payables-month-title" @click="openPlannerDetail(item.month)"><h3>{{ monthLabel(item.month) }}</h3><span>View month details</span></button></div><strong :class="{critical:plannerTotals.find(row=>row.month===item.month)?.headroom<0}">{{ amount(item.total) }}</strong></header><div class="payables-week-grid"><button v-for="week in item.weeks" :key="week.week" @click="openPlannerDetail(item.month,week.week)"><small>Week {{ week.week+1 }} · {{ week.week===4?'29–month end':`${week.week*7+1}–${Math.min((week.week+1)*7,31)}` }}</small><strong>{{ amount(week.total) }}</strong></button></div><div class="payables-month-foot"><span>ERP bills {{ amount(plannerTotals.find(row=>row.month===item.month)?.invoices||0) }}</span><span>Forecast {{ amount(plannerTotals.find(row=>row.month===item.month)?.recurring||0) }}</span><span>Ceiling {{ amount(plannerTotals.find(row=>row.month===item.month)?.ceiling||0) }}</span></div><button v-if="plannerTotals.find(row=>row.month===item.month)?.headroom<0" :disabled="saving" @click="pushDiscretionary(item.month)">Move discretionary ERP allocations to next month</button></article></section>
      <section v-else-if="plannerView==='rows'" class="payables-panel"><div class="payables-panel-head"><div><h2>Allocation rows</h2><p>Group saved allocations by supplier, expense head or branch.</p></div><label>Group<select v-model="plannerGroup"><option value="vendor">Vendor</option><option value="head">Expense head</option><option value="branch">Branch</option></select></label></div><div class="payables-table-wrap"><table><thead><tr><th>{{ plannerGroup==='vendor'?'Vendor':plannerGroup==='branch'?'Branch':'Expense head' }}</th><th>Open balance</th><th v-for="month in plannerHorizonMonths" :key="month">{{ monthLabel(month) }}</th><th>Allocated total</th></tr></thead><tbody><tr v-for="row in plannerGroupedRows" :key="row.name"><td>{{ row.name }}</td><td>{{ amount(row.outstanding) }}</td><td v-for="month in plannerHorizonMonths" :key="month">{{ amount(row.months[month]||0) }}</td><td>{{ amount(row.scheduled) }}</td></tr><tr v-for="item in plannerTotals" :key="'forecast-'+item.month"><td>Recurring forecast · {{ monthLabel(item.month) }}</td><td>—</td><td v-for="month in plannerHorizonMonths" :key="month">{{ month===item.month?amount(item.recurring):'—' }}</td><td>{{ amount(item.recurring) }}</td></tr></tbody></table></div></section>
      <section v-else class="payables-panel"><div class="payables-panel-head"><div><h2>Cash ladder</h2><p>Opening ERP payable book less scheduled ERP allocations, alongside separate recurring assumptions.</p></div></div><div class="payables-table-wrap"><table><thead><tr><th>Month</th><th>Opening ERP book</th><th>Scheduled ERP bills</th><th>Recurring forecast</th><th>Total forecast outflow</th><th>Ceiling assumption</th><th>Headroom</th><th>Closing ERP book</th></tr></thead><tbody><tr v-for="(item,index) in plannerTotals" :key="item.month"><td>{{ monthLabel(item.month) }}</td><td>{{ amount(Math.max(0,totals.outstanding-plannerTotals.slice(0,index).reduce((s,row)=>s+row.invoices,0))) }}</td><td>{{ amount(item.invoices) }}</td><td>{{ amount(item.recurring) }}</td><td>{{ amount(item.total) }}</td><td>{{ amount(item.ceiling) }}</td><td :class="{critical:item.headroom<0}">{{ amount(item.headroom) }}</td><td>{{ amount(Math.max(0,totals.outstanding-plannerTotals.slice(0,index+1).reduce((s,row)=>s+row.invoices,0))) }}</td></tr></tbody></table></div></section>
    </section>
    <section v-else-if="view==='advances'" class="payables-content"><div class="payables-panel-head"><div><h2>Advances &amp; credits</h2><p>Supplier credit balances from the supplier ledger. Read-only.</p></div><button @click="exportRows(advances.filter(inBranch),'payables-advances.csv')">Export CSV</button></div><div class="payables-cards"><article><span>Total credits</span><strong>{{ amount(advances.filter(inBranch).reduce((s,row)=>s+row.a,0)) }}</strong></article><article><span>Payment Entry credits</span><strong>{{ amount(advances.filter(row=>inBranch(row)&&row.src==='PE').reduce((s,row)=>s+row.a,0)) }}</strong></article><article><span>Journal Entry credits</span><strong>{{ amount(advances.filter(row=>inBranch(row)&&row.src==='JE').reduce((s,row)=>s+row.a,0)) }}</strong></article><article><span>Invoice credits</span><strong>{{ amount(advances.filter(row=>inBranch(row)&&row.src==='PI').reduce((s,row)=>s+row.a,0)) }}</strong></article></div><div class="payables-table-wrap"><table><thead><tr><th>Reference</th><th>Supplier</th><th>Branch</th><th>Posting date</th><th>Due date</th><th>Credit balance</th></tr></thead><tbody><tr v-for="row in advances.filter(inBranch)" :key="row.src+'::'+row.i"><td>{{ row.i }}<small>{{ row.s }}</small></td><td>{{ row.v }}</td><td>{{ row.b }}</td><td>{{ dateText(row.d) }}</td><td>{{ dateText(row.u) }}</td><td class="numeric">{{ amount(row.a) }}</td></tr><tr v-if="!advances.filter(inBranch).length"><td colspan="6" class="payables-empty">No supplier credits in this scope.</td></tr></tbody></table></div></section>
    <section v-else-if="view==='paysheet'" class="payables-content"><div class="payables-panel-head"><div><h2>Salary register</h2><p>Read-only submitted Salary Slip records from ERP. The former page's hand-entered sample payroll figures are not reused.</p></div><button :disabled="salaryLoading" @click="loadSalary">{{ salaryLoading?'Loading…':'↻ Refresh Salary Slips' }}</button></div><div class="payables-alert info"><span>This register is read-only. Payroll approval and attendance locking remain in the HR/payroll workflow.</span></div><p v-if="salaryError" class="payables-alert error" role="alert">{{ salaryError }}</p><p v-if="salaryLoading" class="payables-loading" role="status">Loading permission-checked submitted Salary Slips…</p><div class="payables-cards"><article><span>Submitted slips</span><strong>{{ salaryRows.length }}</strong></article><article><span>Net pay in returned rows</span><strong>{{ amount(salaryRows.reduce((s,row)=>s+Number(row.base_net_pay||row.net_pay||0),0)) }}</strong></article><article><span>Salary months</span><strong>{{ salaryMonths.length }}</strong></article></div><div class="payables-table-wrap"><table><thead><tr><th>Month</th><th>Salary Slips</th><th>Net pay</th></tr></thead><tbody><tr v-for="row in salaryMonths" :key="row.month"><td>{{ monthLabel(row.month) }}</td><td>{{ row.count }}</td><td class="numeric">{{ amount(row.net) }}</td></tr><tr v-if="!salaryMonths.length&&!salaryLoading"><td colspan="3" class="payables-empty">No permitted submitted Salary Slip rows were returned.</td></tr></tbody></table></div><section class="payables-panel"><div class="payables-panel-head"><div><h2>Submitted Salary Slip records</h2><p>Open the ERP document to review full earnings, deductions and employee detail.</p></div></div><div class="payables-table-wrap"><table><thead><tr><th>Salary Slip</th><th>Period</th><th>Posting date</th><th>Branch</th><th>Status</th><th>Net pay</th><th>ERP</th></tr></thead><tbody><tr v-for="row in salaryRows" :key="row.name"><td>{{ row.name }}</td><td>{{ dateText(row.start_date) }} – {{ dateText(row.end_date) }}</td><td>{{ dateText(row.posting_date) }}</td><td>{{ row.branch||'—' }}</td><td>{{ row.status||'Submitted' }}</td><td class="numeric">{{ amount(row.base_net_pay||row.net_pay) }}</td><td><a :href="`/app/salary-slip/${encodeURIComponent(row.name)}`" target="_blank" rel="noopener">Open ERP ↗</a></td></tr></tbody></table></div></section></section>
    <section v-else-if="view==='masters'" class="payables-content"><div class="payables-panel-head"><div><h2>Payables masters &amp; planning rules</h2><p>Priority and terms carried over from the legacy planner, plus browser-local ceiling assumptions.</p></div><div><button @click="resetCeilings">Reset ceiling assumptions</button><button class="payables-primary" @click="saveCeilings">Save locally</button></div></div><div class="payables-alert info"><span>Ceilings and priority rules are planning assumptions in this Vue page. Ceiling edits are stored only in this browser; the current API has no persisted ceiling or expense-head master write action.</span></div><section class="payables-panel"><div class="payables-panel-head"><div><h2>Monthly cash ceilings</h2><p>Reference defaults: {{ amount(4500000) }} this month and {{ amount(6800000) }} per later month.</p></div></div><div class="payables-table-wrap"><table><thead><tr><th>Month</th><th>Ceiling assumption</th><th>ERP scheduled</th><th>Recurring forecast</th><th>Headroom</th></tr></thead><tbody><tr v-for="item in plannerTotals" :key="item.month"><td>{{ monthLabel(item.month) }}</td><td><input type="number" min="0" step="50000" :value="ceilings[item.month]??defaultCeiling(item.month)" @input="setCeiling(item.month,$event.target.value)"></td><td class="numeric">{{ amount(item.invoices) }}</td><td class="numeric">{{ amount(item.recurring) }}</td><td :class="{critical:item.headroom<0}">{{ amount(item.headroom) }}</td></tr></tbody></table></div></section><section class="payables-panel"><div class="payables-panel-head"><div><h2>Expense head priority &amp; terms</h2><p>Used by auto-scheduling: priority 1 goes to week 1, other priorities to week 3.</p></div></div><div class="payables-table-wrap"><table><thead><tr><th>Expense head</th><th>Auto-schedule priority</th><th>Default credit terms</th><th>Open lines</th><th>Outstanding</th><th>Scheduling rule</th></tr></thead><tbody><tr v-for="[name,priority,terms] in headRules" :key="name"><td>{{ name }}</td><td>{{ priority===1?'1 · Fixed':priority===2?'2 · Essential':'3 · Discretionary' }}</td><td>{{ terms?`${terms} days`:'Statutory due date' }}</td><td>{{ scoped.filter(row=>row.e===name).length }}</td><td class="numeric">{{ amount(scoped.filter(row=>row.e===name).reduce((s,row)=>s+row.a,0)) }}</td><td>{{ priority===1?'Schedule first':priority===2?'Schedule after fixed obligations':'Can be moved to manage ceiling breaches' }}</td></tr></tbody></table></div></section><section class="payables-panel"><div class="payables-panel-head"><div><h2>Possible duplicate supplier names</h2><p>Names with a matching first 12 normalized characters; review in the ERP before any merge.</p></div></div><div v-for="(group,index) in possibleVendorAliases" :key="index" class="payables-alias-row"><span v-for="name in group" :key="name">{{ name }}</span></div><p v-if="!possibleVendorAliases.length" class="payables-empty">No possible supplier aliases were found in the current branch scope.</p><p class="payables-footnote">Supplier merges must be completed in the source accounting system, then the ledger can be refreshed.</p></section><section class="payables-panel"><div class="payables-panel-head"><div><h2>Operational rules</h2><p>Behavior represented by the live payable actions and the planner.</p></div></div><ul class="payables-rules"><li>A schedule cannot exceed the open supplier balance.</li><li>Statutory liabilities cannot be put on hold.</li><li>Incomplete records need an expense head and branch before scheduling.</li><li>Putting a bill on hold clears its saved payout schedule.</li><li>Recurring forecast rows are assumptions and do not create ERP bills.</li></ul></section></section>
    <section v-else-if="view==='vendors'" class="payables-content"><div class="payables-panel-head"><div><h2>Vendor exposure</h2><p>Outstanding balance, scheduled value and unplanned exposure by supplier.</p></div><label>Find vendor<input v-model="search" type="search" placeholder="Supplier name"></label></div><div class="payables-vendor-grid"><button v-for="item in vendors.filter(row=>!search||row.name.toLowerCase().includes(search.toLowerCase()))" :key="item.name" :class="{active:vendor===item.name}" @click="vendor=item.name"><span>{{ item.name }}</span><strong>{{ amount(item.outstanding) }}</strong><small>{{ item.count }} lines · {{ amount(item.scheduled) }} scheduled</small></button></div><section v-if="vendor" class="payables-panel"><div class="payables-panel-head"><div><h2>{{ vendor }}</h2><p>{{ selectedRows.length }} payable line(s) · {{ amount(selectedRows.reduce((s,row)=>s+row.a,0)) }} outstanding.</p></div><button @click="vendor=''">Close detail</button></div><div class="payables-table-wrap"><table><thead><tr><th>Reference</th><th>Invoice</th><th>Expense head</th><th>Due date</th><th>Ageing</th><th>Outstanding</th><th>Scheduled</th></tr></thead><tbody><tr v-for="row in selectedRows" :key="row.src+'::'+row.i" @click="openRow(row)"><td>{{ row.i }}</td><td>{{ row.n }}</td><td>{{ row.e||'Unassigned' }}</td><td>{{ dateText(row.u) }}</td><td>{{ ageing(row) }}</td><td class="numeric">{{ amount(row.a) }}</td><td class="numeric">{{ amount(planned(row)) }}</td></tr></tbody></table></div><div class="payables-month-bars"><span v-for="item in plannerTotals" :key="item.month" :title="`${monthLabel(item.month)} ${amount(selectedRows.reduce((s,row)=>s+schedMonth(row,item.month),0))}`"><i :style="{height:`${Math.max(3,selectedRows.length?selectedRows.reduce((s,row)=>s+schedMonth(row,item.month),0)/Math.max(1,...plannerTotals.map(m=>selectedRows.reduce((s,row)=>s+schedMonth(row,m.month),0)))*100:3)}%`}"></i></span></div></section></section>
    <section v-else-if="view==='reports'" class="payables-content"><div class="payables-panel-head"><div><h2>Payables reports</h2><p>Reports are calculated from the current branch scope and live payable rows.</p></div><button @click="exportReport()">Export CSV</button></div><div class="payables-report-tabs"><button v-for="[id,label] in [['age','Ageing'],['vendors','Vendor-wise'],['head','Expense head'],['unplanned','Unplanned'],['stat','Statutory'],['calendar','Statutory calendar'],['hold','On hold'],['advice','Due in 7 days'],['salary','Salary register']]" :key="id" :class="{active:report===id}" @click="report=id;id==='salary'&&loadSalary()">{{ label }}</button></div><div class="payables-table-wrap"><table v-if="report==='age'"><thead><tr><th>Ageing bucket</th><th>Vendors</th><th>Lines</th><th>Outstanding</th><th>Scheduled</th><th>Unplanned</th><th>Book share</th></tr></thead><tbody><tr v-for="row in reportRows()" :key="row.name"><td>{{ row.name }}</td><td>{{ row.vendors }}</td><td>{{ row.count }}</td><td class="numeric">{{ amount(row.outstanding) }}</td><td class="numeric">{{ amount(row.scheduled) }}</td><td class="numeric">{{ amount(row.unplanned) }}</td><td>{{ totals.outstanding?Math.round(row.outstanding/totals.outstanding*100):0 }}%</td></tr></tbody></table><table v-else-if="report==='vendors'"><thead><tr><th>Vendor</th><th>Lines</th><th>Oldest overdue</th><th>Outstanding</th><th>Scheduled</th><th>Unplanned</th></tr></thead><tbody><tr v-for="row in reportRows()" :key="row.name" @click="vendor=row.name;setView('vendors')"><td>{{ row.name }}</td><td>{{ row.count }}</td><td>{{ row.oldest }} days</td><td class="numeric">{{ amount(row.outstanding) }}</td><td class="numeric">{{ amount(row.scheduled) }}</td><td class="numeric">{{ amount(Math.max(0,row.outstanding-row.scheduled)) }}</td></tr></tbody></table><table v-else-if="report==='head'"><thead><tr><th>Expense head</th><th>Outstanding</th><th>Scheduled</th><th>Unplanned</th></tr></thead><tbody><tr v-for="row in reportRows()" :key="row.head"><td>{{ row.head }}</td><td class="numeric">{{ amount(row.outstanding) }}</td><td class="numeric">{{ amount(row.scheduled) }}</td><td class="numeric">{{ amount(row.unplanned) }}</td></tr></tbody></table><table v-else-if="report==='salary'"><thead><tr><th>Salary month</th><th>Submitted slips</th><th>Net pay</th></tr></thead><tbody><tr v-for="row in reportRows()" :key="row.month"><td>{{ monthLabel(row.month) }}</td><td>{{ row.count }}</td><td class="numeric">{{ amount(row.net) }}</td></tr><tr v-if="!reportRows().length"><td colspan="3" class="payables-empty">{{ salaryLoading?'Loading Salary Slips…':'No permitted Salary Slip records were returned.' }}</td></tr></tbody></table><table v-else><thead><tr><th>Reference</th><th>Vendor</th><th>Head</th><th>Due date</th><th>Age</th><th>Outstanding</th><th>Scheduled</th><th>Unplanned</th></tr></thead><tbody><tr v-for="row in reportRows()" :key="row.src+'::'+row.i" @click="openRow(row)"><td>{{ row.i }}</td><td>{{ row.v }}</td><td>{{ row.e||'Unassigned' }}</td><td>{{ dateText(row.u) }}</td><td>{{ row.g }} days</td><td class="numeric">{{ amount(row.a) }}</td><td class="numeric">{{ amount(planned(row)) }}</td><td class="numeric">{{ amount(unplanned(row)) }}</td></tr></tbody></table></div></section>
    <p v-if="loading" class="payables-loading" role="status">Loading permission-checked supplier payable records…</p>

    <div v-if="selected" class="payables-overlay" @click.self="closeDialogs"><section class="payables-dialog"><header><div><span class="payables-kicker">{{ selected.s }} · {{ selected.i }}</span><h2>{{ selected.v }}</h2><p>{{ selected.n }} · {{ selected.b }}</p></div><button @click="closeDialogs">Close</button></header><div v-if="selected.localDraft" class="payables-alert info"><span>Browser-local planning draft. This is not an ERP payable and is excluded from live ERP totals.</span></div><div class="payables-detail-grid"><article><span>Open balance</span><strong>{{ amount(selected.a) }}</strong></article><article><span>Due date</span><strong>{{ dateText(selected.u) }}</strong></article><article><span>Ageing</span><strong>{{ selected.g>0?`${selected.g} days overdue`:dateText(selected.u) }}</strong></article><article><span>Scheduled</span><strong>{{ amount(planned(selected)) }}</strong></article><article><span>Expense head</span><strong>{{ selected.e||'Unassigned' }}</strong></article><article><span>Ledger status</span><strong>{{ selected.inc?'Incomplete':selected.x==='H'?'On hold':'Open' }}</strong></article></div><div v-if="selected.inc&&!selected.localDraft" class="payables-complete"><h3>Complete payable record</h3><label>Expense head<input v-model="completeForm.head" placeholder="Enter expense head"></label><label>Branch<select v-model="completeForm.branch"><option value="">Choose branch</option><option v-for="item in branches" :key="item">{{ item }}</option><option v-if="selected.b==='Unassigned'">Unassigned</option></select></label><button class="payables-primary" :disabled="saving" @click="completeLine">{{ saving?'Saving…':'Save head and branch' }}</button></div><section v-if="!selected.inc&&selected.x!=='H'"><h3>Saved payment plan</h3><div class="payables-table-wrap"><table><thead><tr><th>Month</th><th v-for="n in 5" :key="n">Week {{ n }}</th><th>Total</th></tr></thead><tbody><tr v-for="month in Object.keys(selected.p||{}).sort()" :key="month"><td>{{ monthLabel(month) }}</td><td v-for="n in 5" :key="n">{{ amount(selected.p[month]?.[n-1]||0) }}</td><td>{{ amount(scheduleMonthTotal(selected.p,month)) }}</td></tr><tr v-if="!Object.keys(selected.p||{}).length"><td colspan="7" class="payables-empty">No payout weeks have been assigned.</td></tr></tbody></table></div></section><footer><button v-if="selected.localDraft" @click="deleteDraft(selected)">Delete draft</button><button v-else @click="vendor=selected.v;setView('vendors');selected=null">Vendor view</button><button v-if="selected.x==='H'" class="payables-primary" :disabled="saving" @click="toggleHold(selected)">{{ saving?'Saving…':'Release hold' }}</button><template v-else><button v-if="!selected.inc" :disabled="(!selected.localDraft&&isStatutory(selected))||saving" @click="toggleHold(selected)">Put on hold</button><button v-if="!selected.inc" class="payables-primary" @click="openSchedule(selected);selected=null">Edit payout schedule</button></template></footer></section></div>
    <div v-if="plannerDetail" class="payables-overlay" @click.self="plannerDetail=null"><section class="payables-dialog wide"><header><div><span class="payables-kicker">PAYOUT CALENDAR</span><h2>{{ monthLabel(plannerDetail.month) }}<template v-if="Number.isInteger(plannerDetail.week)"> · Week {{ plannerDetail.week+1 }}</template></h2><p>ERP payout allocations and clearly separated forecast assumptions.</p></div><button @click="plannerDetail=null">Close</button></header><div class="payables-table-wrap"><table><thead><tr><th>Type</th><th>Supplier / commitment</th><th>Reference</th><th>Expense head</th><th>Amount</th><th></th></tr></thead><tbody><tr v-for="(item,index) in plannerDetailRows" :key="item.reference+'::'+index"><td>{{ item.kind }}</td><td>{{ item.name }}</td><td>{{ item.reference }}</td><td>{{ item.head }}</td><td class="numeric">{{ amount(item.amount) }}</td><td><button v-if="item.row" class="payables-link" @click="selected=item.row;plannerDetail=null">Open payable</button></td></tr><tr v-if="!plannerDetailRows.length"><td colspan="6" class="payables-empty">No bills or forecast items in this time slot.</td></tr></tbody></table></div></section></div>
    <div v-if="schedule" class="payables-overlay" @click.self="closeDialogs"><section class="payables-dialog wide"><header><div><span class="payables-kicker">SCHEDULE PAYOUT</span><h2>{{ schedule.row.v }} · {{ schedule.row.i }}</h2><p>{{ amount(schedule.row.a) }} open · due {{ dateText(schedule.row.u) }}</p></div><button @click="closeDialogs">Close</button></header><div class="payables-quick"><button @click="quickSchedule('now')">Full amount next week</button><button @click="quickSchedule('due')">Full amount on due date</button><button @click="quickSchedule('3')">Split over 3 months</button><button @click="quickSchedule('6')">Split over 6 months</button><button @click="schedule.plan={}">Clear</button></div><div class="payables-table-wrap"><table><thead><tr><th>Month</th><th v-for="n in 5" :key="n">Week {{ n }}</th><th>Month total</th></tr></thead><tbody><tr v-for="month in plannerMonths" :key="month"><td>{{ monthLabel(month) }}</td><td v-for="n in 5" :key="n"><input type="number" min="0" step="100" :value="schedule.plan[month]?.[n-1]||''" @input="setWeek(month,n-1,$event.target.value)"></td><td>{{ amount(scheduleMonthTotal(schedule.plan,month)) }}</td></tr></tbody></table></div><p class="payables-schedule-total">Allocated {{ amount(editingTotal) }} of {{ amount(schedule.row.a) }} <strong :class="{critical:editingTotal>schedule.row.a+.01}">{{ editingTotal>schedule.row.a+.01?'Over balance':'Within open balance' }}</strong></p><footer><button @click="closeDialogs">Cancel</button><button class="payables-primary" :disabled="saving||editingTotal>schedule.row.a+.01" @click="saveSchedule">{{ saving?'Saving…':'Save payout plan' }}</button></footer></section></div>
  </main>
</template>
